draw:
var b = p.b, vSel = p.v;
var vMax = 30;
var padL = 46, padB = 30, padT = 16, padR = 14;
var plotW = W - padL - padR, plotH = H - padT - padB;
var Pmax = b * Math.pow(vMax, 3);
var X = function (v) { return padL + plotW * (v / vMax); };
var Y = function (P) { return padT + plotH * (1 - P / Pmax); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, padT + plotH); ctx.lineTo(padL + plotW, padT + plotH);
ctx.stroke();

// cubic curve
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 140; i++) {
  var v = vMax * i / 140;
  i === 0 ? ctx.moveTo(X(v), Y(0)) : ctx.lineTo(X(v), Y(b * v * v * v));
}
ctx.stroke();
ctx.lineWidth = 1;

// selected speed and double it
var P1 = b * vSel * vSel * vSel;
var v2 = Math.min(2 * vSel, vMax);
var P2 = b * v2 * v2 * v2;

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(vSel), padT + plotH); ctx.lineTo(X(vSel), Y(P1)); ctx.lineTo(padL, Y(P1)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(v2), padT + plotH); ctx.lineTo(X(v2), Y(P2)); ctx.lineTo(padL, Y(P2)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(vSel), Y(P1), 5, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(v2), Y(P2), 5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("P (kW)", 4, padT + 10);
ctx.fillText("v (m/s)", padL + plotW - 34, padT + plotH + 20);
ctx.fillText("P = b v^3", padL + plotW - 70, padT + 24);
ctx.fillStyle = C.faint;
ctx.fillText("0", padL - 8, padT + plotH + 16);
ctx.fillText(vMax.toFixed(0), padL + plotW - 6, padT + plotH + 16);
ctx.fillText((Pmax / 1000).toFixed(0), 6, padT + plotH - 2);
ctx.fillStyle = C.accent;
ctx.fillText("v", X(vSel) - 3, padT + plotH + 16);
ctx.fillText("2v", X(v2) - 6, padT + plotH + 16);

out.note = "at " + vSel.toFixed(1) + " m/s need " + (P1 / 1000).toFixed(2)
  + " kW; at " + v2.toFixed(1) + " m/s need " + (P2 / 1000).toFixed(2)
  + " kW, a factor of " + (P1 > 0 ? (P2 / P1).toFixed(2) : "-");
